import React, { useState } from 'react';

function Lobby({ onJoinGame, onCreateGame }) {
  const [gameId, setGameId] = useState('');
  const [playerName, setPlayerName] = useState('');

  const handleJoinSubmit = (e) => {
    e.preventDefault();
    if (gameId.trim() && playerName.trim()) {
      onJoinGame(gameId.trim(), playerName.trim());
    }
  };

  const handleCreateGame = () => {
    if (playerName.trim()) {
      onCreateGame(playerName.trim());
    }
  };

  return (
    <div className="lobby">
      <h2>Join UNO Game</h2>
      <form onSubmit={handleJoinSubmit}>
        <div className="form-group">
          <label htmlFor="gameId">Game ID:</label>
          <input
            type="text"
            id="gameId"
            value={gameId}
            onChange={(e) => setGameId(e.target.value)}
            placeholder="Enter game ID"
            required
          />
        </div>
        <div className="form-group">
          <label htmlFor="playerName">Your Name:</label>
          <input
            type="text"
            id="playerName"
            value={playerName}
            onChange={(e) => setPlayerName(e.target.value)}
            placeholder="Enter your name"
            required
          />
        </div>
        <button type="submit" className="join-button">Join Game</button>
      </form>
      <div className="create-game-section">
        <p>Or create a new game:</p>
        <button onClick={handleCreateGame} className="create-button" disabled={!playerName.trim()}>
          Create New Game
        </button>
      </div>
      <p className="instructions">
        Ask the game host for the Game ID to join an existing game, or create a new one to get a Game ID.
      </p>
    </div>
  );
}

export default Lobby;
